state.template:
function {{id}}(payload) {
  if (typeof __step === 'function') __step('{{id}}');
  const key = {{key}};
  const op = {{op}};
  let result;
  if (op === 'set') {
    const val = payload !== undefined ? payload : {{valExpr}};
    result = setVar(key, val);
  } else if (op === 'toggle') {
    result = setVar(key, !getVar(key));
  } else if (op === 'clear' || op === 'remove') {
    result = clearVar(key);
  } else {
    result = getVar(key, {{valExpr}});
  }
  {{nextCall}}
  return result;
}

